let out = {}, errors = null
try {
    // a JSON parameter from the request body only (a mapping may hold a SQL source), never the URL
    const body = (name, fallback) => {
        const text = ec.web.secureRequestParameters[name]
        if (text == null || text === '') return fallback
        try { return JSON.parse(String(text)) } catch (e) { throw new Error(name + ' is not JSON') }
    }
    const term = String(context.term || '').toLowerCase()
    const kind = String(context.targetTypeEnumId || 'EtltEntity')
    const names = !term ? [] : kind == 'EtltService' ? Array.from(ec.service.knownServiceNames || []).filter((name) => String(name).toLowerCase().includes(term) && !String(name).includes('.delete#')).sort().slice(0, 50)
        : ec.entity.getAllEntityNames().filter((name) => String(name).toLowerCase().includes(term)).slice(0, 50)
    const valueMaps = ec.entity.find('moqui.etl.EtlValueMap').orderBy('valueMapId').list().map((row) => ({valueMapId: row.valueMapId, description: row.description}))
    out = {targetNames: names, valueMaps, canExpression: ec.user.hasPermission('GROOVY_SHELL_WEB'), canSql: ec.user.hasPermission('SQL_RUNNER_WEB'),
        userId: ec.user.userId, isAdmin: ec.user.hasPermission('DATABASE_ADMIN')}
} catch (e) { errors = String(e.message || e) }
if (ec.message.hasError()) errors = ec.message.errorsString
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))

