let out = {}, errors = null, jobName = null
const failed = () => ec.message.hasError()
try {
    const mappingId = String(context.mappingId || '')
    const cronExpression = String(context.cronExpression || '').trim()
    if (!mappingId || !cronExpression) throw new Error('A schedule needs a mapping and a cron expression')
    // the framework's Quartz cron parser: it throws on a bad expression, and null is one that is never due
    let nextRun = null
    try { nextRun = ec.service.nextCronExecution(cronExpression, null) } catch (e) { throw new Error('Not a cron expression: ' + String(e.message || e)) }
    if (nextRun == null) throw new Error('The cron expression ' + cronExpression + ' is never due')
    // the same check as a change of the mapping: store it as it is
    const mapping = (ec.service.sync().name('org.moqui.impl.EtlServices.get#EtlMapping').parameters({mappingId}).call() || {}).mapping
    if (!mapping || failed()) throw new Error(ec.message.errorsString || 'No mapping ' + mappingId)
    ec.service.sync().name('org.moqui.impl.EtlServices.store#EtlMapping').parameters({mapping}).call()
    if (failed()) throw new Error(ec.message.errorsString)
    // a name of at most 60 that keeps its unique end: the mapping id is cut, never the time and random part
    const unique = '_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6)
    jobName = 'EtlMapping_' + mappingId.slice(0, 60 - 'EtlMapping_'.length - unique.length) + unique
    // made paused, and unpaused only once its parameter and user are there, so the scheduler never sees half
    ec.service.sync().name('create#moqui.service.job.ServiceJob').parameters({jobName, description: 'ETL mapping ' + (mapping.description || mappingId),
        serviceName: 'org.moqui.impl.EtlServices.run#EtlMapping', cronExpression, paused: 'Y'}).call()
    if (failed()) { jobName = null; throw new Error(ec.message.errorsString) }
    ec.service.sync().name('create#moqui.service.job.ServiceJobParameter').parameters({jobName, parameterName: 'mappingId', parameterValue: mappingId}).call()
    if (failed()) throw new Error(ec.message.errorsString)
    // the job's user is the mapping's owner (an admin may schedule another's mapping): run#EtlMapping runs a
    // scheduled job as the owner only when this row names that owner; the owner is told of each run
    ec.service.sync().name('create#moqui.service.job.ServiceJobUser').parameters({jobName, userId: mapping.ownerUserId || ec.user.userId, receiveNotifications: 'Y'}).call()
    if (failed()) throw new Error(ec.message.errorsString)
    ec.service.sync().name('update#moqui.service.job.ServiceJob').parameters({jobName, paused: 'N'}).call()
    if (failed()) throw new Error(ec.message.errorsString)
    out = {jobName, nextRun}
} catch (e) {
    errors = String(e.message || e)
    // remove what was made, each piece on its own
    if (jobName) {
        ec.message.clearErrors()
        for (const name of ['ServiceJobUser', 'ServiceJobParameter', 'ServiceJob']) {
            try { ec.entity.find('moqui.service.job.' + name).condition('jobName', jobName).deleteAll() }
            catch (cleanup) { ec.logger.error('ETL schedule: could not remove ' + name + ' of ' + jobName + ': ' + String(cleanup.message || cleanup)) }
        }
    }
}
if (!errors && ec.message.hasError()) errors = ec.message.errorsString
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))
